final class DeepTests{
 static void register(DeferredRegister<Consumer<GameTestHelper>> f){
  f.register("deep_processing",()->DeepTests::processing);f.register("deep_guards",()->DeepTests::guards);f.register("deep_energy",()->DeepTests::energy);f.register("deep_hoppers",()->DeepTests::hoppers);f.register("deep_service",()->DeepTests::service);f.register("deep_turbine",()->DeepTests::turbine);f.register("deep_restore",()->DeepTests::restore);f.register("deep_bore",()->DeepTests::bore);f.register("deep_bore_guards",()->DeepTests::boreGuards);f.register("deep_dredger",()->DeepTests::dredger);f.register("deep_equipment",()->DeepTests::equipment);f.register("deep_worldgen",()->DeepTests::worldgen);
  f.register("depths_architecture",()->DeepTests::architecture);f.register("depths_entrance",()->DeepTests::entrance);f.register("depths_ledger",()->DeepTests::ledger);f.register("depths_encounter",()->DeepTests::encounter);f.register("depths_rewards",()->DeepTests::rewards);f.register("depths_restore",()->DeepTests::depthsRestore);f.register("depths_migration",()->DeepTests::migration);f.register("depths_boss_patterns",()->DeepTests::patterns);
 }
 static void check(GameTestHelper h,boolean b,String m){h.assertTrue(b,Component.literal(m));}
 static DeepMachineEntity machine(GameTestHelper h,DeepIndustry.Kind k){var at=h.absolutePos(new BlockPos(10,6,10));h.getLevel().setBlock(at,DeepIndustry.MACHINES.get(k).get().defaultBlockState(),3);return (DeepMachineEntity)h.getLevel().getBlockEntity(at);}
 static void frame(GameTestHelper h,DeepMachineEntity e){var w=h.getLevel();var p=e.getBlockPos();int r=e.kind==DeepIndustry.Kind.BORE?3:1;for(int x=-r;x<=r;x++)for(int z=-r;z<=r;z++)if(r==1&&(x!=0||z!=0)||r==3&&(Math.abs(x)==3||Math.abs(z)==3))w.setBlock(p.offset(x,-1,z),Industry.FRAME.get().defaultBlockState(),3);if(e.kind!=DeepIndustry.Kind.DREDGER)for(int x:new int[]{-r,r})for(int z:new int[]{-r,r})for(int y=0;y<=(r==3?4:1);y++)w.setBlock(p.offset(x,y,z),Industry.FRAME.get().defaultBlockState(),3);if(r==3)for(int x=-3;x<=3;x++)w.setBlock(p.offset(x,5,0),Industry.FRAME.get().defaultBlockState(),3);}
 static void arm(GameTestHelper h,DeepMachineEntity e){var p=GameplayTests.player(h);try{p.setPos(Vec3.atCenterOf(e.getBlockPos().above()));check(h,e.action(p,0),"A nearby player deliberately arms finite excavation");}finally{GameplayTests.cleanup(p);}}
 static void processing(GameTestHelper h){var e=machine(h,DeepIndustry.Kind.CENTRIFUGE);frame(h,e);e.energy.set(12000);e.setItem(0,new ItemStack(DeepIndustry.item("raw_ferronyte"),2));e.setItem(1,new ItemStack(Items.SAND,2));h.runAfterDelay(170,()->{check(h,e.countItem(DeepIndustry.item("ferronyte_grit"))==6&&e.energy.getAmountAsInt()==0&&e.wear()==992,"Two finite raws and sand become six grit at exact FE and service cost");check(h,DeepRecipes.recipes(DeepIndustry.Kind.CENTRIFUGE).stream().noneMatch(r->r.first()==DeepIndustry.item("ferronyte_ingot")),"Ingots cannot recycle through multiplication");h.succeed();});}
 static void guards(GameTestHelper h){var e=machine(h,DeepIndustry.Kind.REPLICATOR);e.energy.set(96000);e.setItem(0,new ItemStack(DeepIndustry.item("raw_asterium")));e.setItem(1,new ItemStack(DeepIndustry.item("mineral_matrix")));h.runAfterDelay(35,()->{check(h,e.status()==1&&e.countItem(DeepIndustry.item("raw_asterium"))==1,"No structure means no resources consumed");frame(h,e);for(int i=3;i<8;i++)e.setItem(i,new ItemStack(Items.COBBLESTONE,64));h.runAfterDelay(340,()->{check(h,e.status()==5&&e.energy.getAmountAsInt()==96000&&e.countItem(DeepIndustry.item("mineral_matrix"))==1&&e.wear()==1000,"Blocked products preserve raw, matrix, all FE and service");for(int i=3;i<8;i++)e.setItem(i,ItemStack.EMPTY);h.getLevel().setBlock(e.getBlockPos().east(),Blocks.REDSTONE_BLOCK.defaultBlockState(),3);h.runAfterDelay(30,()->{check(h,e.status()==2&&e.countItem(DeepIndustry.item("raw_asterium"))==1,"Redstone pauses processing before consumption");h.succeed();});});});}
 static void energy(GameTestHelper h){var e=machine(h,DeepIndustry.Kind.KILN);var port=h.getLevel().getCapability(Capabilities.Energy.BLOCK,e.getBlockPos(),Direction.WEST);try(var t=Transaction.openRoot()){check(h,port.insert(5000,t)==5000,"New machines expose native FE");}check(h,e.energy.getAmountAsInt()==0,"Aborted insertion rolls back");try(var t=Transaction.openRoot()){port.insert(5000,t);t.commit();}try(var t=Transaction.openRoot()){check(h,port.extract(5000,t)==0,"Consumers cannot manufacture energy by extraction");}check(h,e.energy.getAmountAsInt()==5000,"Committed insertion stores exactly 5000 FE");var high=e.getBlockPos().above(20);FieldworkTests.platform(h.getLevel(),high);FieldworkTests.platform(h.getLevel(),high);FieldworkTests.release(h.getLevel(),high);check(h,!h.getLevel().setChunkForced(e.getBlockPos().getX()>>4,e.getBlockPos().getZ()>>4,true),"Overlapping fixtures retain their shared chunk ticket");FieldworkTests.release(h.getLevel(),high);check(h,!h.getLevel().setChunkForced(e.getBlockPos().getX()>>4,e.getBlockPos().getZ()>>4,true),"Fixture cleanup never revokes the native GameTest runner ticket");h.succeed();}
 static void hoppers(GameTestHelper h){var e=machine(h,DeepIndustry.Kind.KILN);frame(h,e);e.energy.set(6000);var w=h.getLevel();w.setBlock(e.getBlockPos().above(),Blocks.HOPPER.defaultBlockState(),3);w.setBlock(e.getBlockPos().east(),Blocks.HOPPER.defaultBlockState().setValue(HopperBlock.FACING,Direction.WEST),3);w.setBlock(e.getBlockPos().below(),Blocks.HOPPER.defaultBlockState(),3);var top=(HopperBlockEntity)w.getBlockEntity(e.getBlockPos().above());var side=(HopperBlockEntity)w.getBlockEntity(e.getBlockPos().east());var bottom=(HopperBlockEntity)w.getBlockEntity(e.getBlockPos().below());top.setItem(0,new ItemStack(DeepIndustry.item("ferronyte_grit"),4));side.setItem(0,new ItemStack(Items.COAL));h.runAfterDelay(150,()->{check(h,top.isEmpty()&&side.isEmpty()&&bottom.countItem(DeepIndustry.item("ferronyte_ingot"))==4&&e.energy.getAmountAsInt()==0,"Real hoppers supply both feeds and export only the four native products");h.succeed();});}
 static DeepMachineEntity reload(GameTestHelper h,DeepMachineEntity e,java.util.function.Consumer<net.minecraft.nbt.CompoundTag> change){var tag=e.saveWithFullMetadata(h.getLevel().registryAccess());change.accept(tag);var n=(DeepMachineEntity)BlockEntity.loadStatic(e.getBlockPos(),e.getBlockState(),tag,h.getLevel().registryAccess());e.setRemoved();n.setLevel(h.getLevel());h.getLevel().setBlockEntity(n);return n;}
 static void service(GameTestHelper h){var e=machine(h,DeepIndustry.Kind.KILN);frame(h,e);e.energy.set(6000);e.setItem(0,new ItemStack(DeepIndustry.item("ferronyte_grit"),4));e.setItem(1,new ItemStack(Items.COAL));var n=reload(h,e,t->t.putInt("wear",0));h.runAfterDelay(90,()->{check(h,n.status()==6&&n.energy.getAmountAsInt()==6000&&n.countItem(Items.COAL)==1,"A worn machine stops without losing material or FE");n.setItem(2,new ItemStack(DeepIndustry.item("maintenance_kit")));h.runAfterDelay(75,()->{check(h,n.wear()==996&&n.getItem(2).isEmpty()&&n.countItem(DeepIndustry.item("ferronyte_ingot"))==4,"One actual kit restores service and permits precisely one paid cycle");h.succeed();});});}
 static void turbine(GameTestHelper h){var initial=machine(h,DeepIndustry.Kind.TURBINE);frame(h,initial);var e=reload(h,initial,t->t.putInt("wear",0));e.setItem(2,new ItemStack(DeepIndustry.item("maintenance_kit")));e.setItem(0,new ItemStack(DeepIndustry.item("resonant_fuel_cell")));e.setItem(1,new ItemStack(Items.WATER_BUCKET));for(int i=3;i<8;i++)e.setItem(i,new ItemStack(Items.COBBLESTONE,64));h.runAfterDelay(25,()->{check(h,e.countItem(DeepIndustry.item("maintenance_kit"))==1&&e.wear()==0&&e.countItem(DeepIndustry.item("resonant_fuel_cell"))==1&&e.countItem(Items.WATER_BUCKET)==1&&e.energy.getAmountAsInt()==0,"A blocked turbine preserves its maintenance kit, fuel, coolant and energy");for(int i=3;i<8;i++)e.setItem(i,ItemStack.EMPTY);h.runAfterDelay(410,()->{check(h,e.energy.getAmountAsInt()==640000&&e.countItem(Items.BUCKET)==1&&e.getItem(0).isEmpty()&&e.getItem(1).isEmpty()&&e.wear()==980,"One finite fuel cell and coolant bucket produce exactly 640000 FE and one empty bucket");var port=h.getLevel().getCapability(Capabilities.Energy.BLOCK,e.getBlockPos(),Direction.DOWN);try(var t=Transaction.openRoot()){check(h,port.extract(16000,t)==16000,"Turbine output is transactional");}check(h,e.energy.getAmountAsInt()==640000,"Aborted output does not destroy FE");h.succeed();});});}
 static void restore(GameTestHelper h){var e=machine(h,DeepIndustry.Kind.BORE);e.energy.set(400000);e.setItem(1,new ItemStack(DeepIndustry.item("hardened_drill_bit")));e.setItem(3,new ItemStack(Items.DIAMOND,7));arm(h,e);var n=reload(h,e,t->{t.putInt("wear",279);t.putInt("cursor",50000);t.putInt("progress",5);});var p=GameplayTests.player(h);try{var menu=new DeepMachineMenu(1,p.getInventory(),n,n.data);check(h,n.wear()==279&&n.cursor()==50000&&n.armed()&&n.countItem(Items.DIAMOND)==7&&menu.energy()==400000&&menu.cursor()==50000,"Native reload and menu preserve FE, inputs, outputs, service, cursor and arming above short range");}finally{GameplayTests.cleanup(p);}h.succeed();}
 static void bore(GameTestHelper h){var e=machine(h,DeepIndustry.Kind.BORE);frame(h,e);e.energy.set(12000);e.setItem(1,new ItemStack(DeepIndustry.item("hardened_drill_bit")));var at=e.getBlockPos().offset(-8,-2,-8);h.getLevel().setBlock(at,Blocks.DIAMOND_ORE.defaultBlockState(),3);h.runAfterDelay(25,()->{check(h,h.getLevel().getBlockState(at).is(Blocks.DIAMOND_ORE),"Bore starts disarmed");arm(h,e);h.runAfterDelay(20,()->{check(h,h.getLevel().isEmptyBlock(at)&&e.countItem(Items.DIAMOND)==1&&e.energy.getAmountAsInt()==0&&e.getItem(1).getDamageValue()==1,"Bore removes the actual native ore once and charges exact FE and physical bit wear");h.succeed();});});}
 static void boreGuards(GameTestHelper h){var e=machine(h,DeepIndustry.Kind.BORE);frame(h,e);arm(h,e);e.energy.set(12000);e.setItem(1,new ItemStack(DeepIndustry.item("hardened_drill_bit")));var at=e.getBlockPos().offset(-8,-2,-8);var w=h.getLevel();w.setBlock(at,Blocks.CHEST.defaultBlockState(),3);((ChestBlockEntity)w.getBlockEntity(at)).setItem(0,new ItemStack(Items.DIAMOND,9));w.setBlock(at.east(),Blocks.BEDROCK.defaultBlockState(),3);w.setBlock(at.east(2),Blocks.IRON_ORE.defaultBlockState(),3);for(int i=3;i<8;i++)e.setItem(i,new ItemStack(Items.COBBLESTONE,64));h.runAfterDelay(40,()->{check(h,((ChestBlockEntity)w.getBlockEntity(at)).countItem(Items.DIAMOND)==9&&w.getBlockState(at.east()).is(Blocks.BEDROCK)&&w.getBlockState(at.east(2)).is(Blocks.IRON_ORE),"Bore preserves inventories, bedrock and paid targets when output is full");check(h,e.energy.getAmountAsInt()==12000&&e.getItem(1).getDamageValue()==0,"Blocked output consumes neither FE nor drill wear");h.succeed();});}
 static void dredger(GameTestHelper h){var e=machine(h,DeepIndustry.Kind.DREDGER);frame(h,e);arm(h,e);e.energy.set(16000);e.setItem(1,new ItemStack(DeepIndustry.item("hardened_drill_bit")));var at=e.getBlockPos().offset(-8,-2,-8);var w=h.getLevel();w.setBlock(at,DeepIndustry.ORES.get("thalassite_nodule").get().defaultBlockState(),3);h.runAfterDelay(30,()->{check(h,e.status()==10&&w.getBlockState(at).is(DeepIndustry.ORES.get("thalassite_nodule").get())&&e.energy.getAmountAsInt()==16000,"A dry/non-ocean dredger cannot conjure seabed resources");
 var biome=w.registryAccess().lookupOrThrow(Registries.BIOME).getOrThrow(ResourceKey.create(Registries.BIOME,Identifier.fromNamespaceAndPath("minecraft","deep_ocean")));net.minecraft.server.commands.FillBiomeCommand.fill(w,e.getBlockPos().offset(-8,-8,-8),e.getBlockPos().offset(8,16,8),biome);for(int y=1;y<=8;y++)w.setBlock(e.getBlockPos().above(y),Blocks.WATER.defaultBlockState(),2);w.setBlock(at.below(),Blocks.STONE.defaultBlockState(),3);
 h.runAfterDelay(75,()->{check(h,w.getBlockState(at).is(Blocks.GRAVEL)&&e.countItem(DeepIndustry.item("raw_thalassite"))==1&&e.energy.getAmountAsInt()==0&&e.getItem(1).getDamageValue()==1,"A real ocean dredger harvests the finite nodule once, replaces the seabed and charges exact FE and bit wear; status="+e.status()+", FE="+e.energy.getAmountAsInt()+", raw="+e.countItem(DeepIndustry.item("raw_thalassite"))+", target="+w.getBlockState(at));h.succeed();});});}
 static void equipment(GameTestHelper h){for(var m:DeepIndustry.Metal.values()){var parts=DeepIndustry.GEAR.get(m);check(h,parts.size()==9,"Each metal has five native tools and four armor pieces");for(var i:parts.values())check(h,new ItemStack(i.get()).isDamageableItem(),"Every equipment item has native durability");}var p=GameplayTests.player(h);try{for(var slot:List.of(net.minecraft.world.entity.EquipmentSlot.HEAD,net.minecraft.world.entity.EquipmentSlot.CHEST,net.minecraft.world.entity.EquipmentSlot.LEGS,net.minecraft.world.entity.EquipmentSlot.FEET)){String part=switch(slot){case HEAD->"helmet";case CHEST->"chestplate";case LEGS->"leggings";default->"boots";};p.setItemSlot(slot,new ItemStack(DeepIndustry.GEAR.get(DeepIndustry.Metal.ASTERIUM).get(part).get()));}check(h,DeepEquipment.complete(p,DeepIndustry.Metal.ASTERIUM),"Real equipment slots activate a complete set");p.setItemSlot(net.minecraft.world.entity.EquipmentSlot.HEAD,ItemStack.EMPTY);check(h,!DeepEquipment.complete(p,DeepIndustry.Metal.ASTERIUM),"Mixed equipment never activates a full-set bonus");}finally{GameplayTests.cleanup(p);}h.succeed();}
 static void worldgen(GameTestHelper h){var w=h.getLevel();var origin=h.absolutePos(new BlockPos(8,5,8));int x0=origin.getX()&~15,z0=origin.getZ()&~15;for(int x=x0;x<x0+16;x++)for(int z=z0;z<z0+16;z++)for(int y=-48;y<=16;y++)w.setBlock(new BlockPos(x,y,z),Blocks.STONE.defaultBlockState(),2);var outside=new BlockPos(x0-1,-20,z0);w.setBlock(outside,Blocks.GOLD_BLOCK.defaultBlockState(),2);int n=new DeepOreFeature(false).generate(w,origin,net.minecraft.util.RandomSource.create(20020));check(h,n>20&&w.getBlockState(outside).is(Blocks.GOLD_BLOCK),"Native ferronyte generation produces real veins without touching a neighbouring chunk");h.succeed();}
 static void architecture(GameTestHelper h){var r=CityRegions.region(200,200);for(int i=0;i<8;i++){var c=DepthsLayout.centre(r,i);check(h,DepthsArchitecture.state(r,c.getX(),17,c.getZ()+18).is(DepthsContent.NODE.get()),"Each hall has its own real combat controller");for(int[] d:new int[][]{{0,0},{24,0},{-24,0},{0,24},{0,-24}}){check(h,!DepthsArchitecture.state(r,c.getX()+d[0],16,c.getZ()+d[1]).isAir()&&DepthsArchitecture.state(r,c.getX()+d[0],17,c.getZ()+d[1]).isAir()&&DepthsArchitecture.state(r,c.getX()+d[0],18,c.getZ()+d[1]).isAir(),"All fighting lanes have a supported floor and two-block headroom");}for(int step=0;step<12;step++){int x=c.getX()-40+step,y=17+step/2,z=c.getZ()+37;check(h,DepthsArchitecture.state(r,x,y+1,z).isAir()&&DepthsArchitecture.state(r,x,y+2,z).isAir(),"Every gallery stair has genuine full-body headroom");if(step%2==0)check(h,DepthsArchitecture.state(r,x,y,z).is(SanctuaryContent.STAIRS.get()),"Half-block stair shapes make the gallery accessible without jumping");}check(h,!DepthsArchitecture.state(r,c.getX()+38,22,c.getZ()+38).isAir(),"Raised galleries add actual volumetric relief");}h.succeed();}
 static void entrance(GameTestHelper h){var site=CityRegions.region(200,200);for(int[] segment:new int[][]{{0,66,0,112},{0,112,-256,112},{-256,112,-256,-96},{-256,-96,-240,-96}}){int dx=Integer.signum(segment[2]-segment[0]),dz=Integer.signum(segment[3]-segment[1]),len=Math.abs(segment[2]-segment[0])+Math.abs(segment[3]-segment[1]);for(int n=0;n<=len;n++){int x=site.x()+segment[0]+dx*n,z=site.z()+segment[1]+dz*n;for(int y=17;y<=18;y++){var b=DepthsArchitecture.state(site,x,y,z);check(h,b!=null&&b.isAir(),"The actual entrance route has continuous two-block headroom");}check(h,!DepthsArchitecture.state(site,x,16,z).isAir(),"The entire entrance route has a solid floor");}}for(int k=-2;k<=2;k++){var r=CityRegions.region(k,-k);var e=DepthsLayout.entrance(r);check(h,e.getY()==89&&e.getX()==r.x()&&e.getZ()==r.z()+64,"One deterministic street entrance per city");for(int y=17;y<=88;y++){check(h,DepthsArchitecture.state(r,r.x(),y,r.z()+64).isAir(),"Single shaft remains open through the entire city plinth");check(h,DepthsArchitecture.state(r,r.x()+2,y,r.z()+64).is(Blocks.LADDER),"Continuous physical ladder reaches the street from below");}}h.succeed();}
 static void ledger(GameTestHelper h){var l=DepthsLedger.get(h.getLevel().getServer());long key=0x2020202020L;var id=UUID.randomUUID();check(h,!l.finish(key,1)&&!l.claim(key,id,1),"Neither route skipping nor early extraction is accepted");check(h,l.finish(key,0)&&l.finish(key,1),"Real linear completion advances in order");l.eligible(key,id,1);check(h,l.claim(key,id,1)&&!l.claim(key,id,1)&&!l.claim(key,UUID.randomUUID(),1),"Reward is personal and idempotent");h.succeed();}
 static final class Fixture implements AutoCloseable{final ServerLevel w;final CityRegions.Region r;final DepthsNodeEntity n;final ServerPlayer p;final List<BlockPos> pads=new ArrayList<>();Fixture(GameTestHelper h,int cell,int i){w=FieldworkTests.vestige(h);r=CityRegions.region(cell,cell);var node=DepthsLayout.node(r,i);for(int j=0;j<12;j++){double a=j*Math.PI/6;var at=node.offset((int)(Math.cos(a)*24),0,-18+(int)(Math.sin(a)*24));FieldworkTests.platform(w,at);pads.add(at);}FieldworkTests.platform(w,node);pads.add(node);w.getChunkAt(node).setData(CityRegions.GENERATED,true);w.getChunkAt(node).setData(DepthsMigration.GENERATED,true);w.setBlock(node,DepthsContent.NODE.get().defaultBlockState(),3);n=(DepthsNodeEntity)w.getBlockEntity(node);for(int j=0;j<i;j++)DepthsLedger.get(w.getServer()).finish(DepthsLayout.key(r),j);p=FieldworkTests.player(h,w,node.east(2));p.addEffect(new net.minecraft.world.effect.MobEffectInstance(net.minecraft.world.effect.MobEffects.RESISTANCE,1800,5));}public void close(){w.getEntitiesOfClass(SanctuaryConstruct.class,new AABB(n.getBlockPos()).inflate(70)).forEach(Entity::discard);GameplayTests.cleanup(p);pads.forEach(at->FieldworkTests.release(w,at));}}
 static void encounter(GameTestHelper h){var f=new Fixture(h,202,0);check(h,f.n.action(f.p,0),"Survival player engages a real city combat node");for(int j=0;j<8;j++)f.n.tick();h.runAfterDelay(3,()->{try{var all=f.w.getEntitiesOfClass(SanctuaryConstruct.class,new AABB(f.n.getBlockPos()).inflate(65));check(h,all.size()==12&&f.n.spawned()==12,"The combat wave is dense and capped at twelve live actors");all.getFirst().discard();f.n.tick();check(h,f.n.killed()==0&&f.n.mask()==0,"Unloaded or discarded actors do not become free kills");check(h,f.n.accepts(all.get(1).getUUID(),all.get(1).token()),"New actors are bound to their genuine home controller");h.succeed();}finally{f.close();}});}
 static void finishAttempt(GameTestHelper h,Fixture f,int remaining,Runnable done){if(remaining<=0){f.close();check(h,false,"Combat failed to terminate");return;}f.n.tick();for(var e:f.w.getEntitiesOfClass(SanctuaryConstruct.class,new AABB(f.n.getBlockPos()).inflate(65)))e.hurtServer(f.w,f.w.damageSources().genericKill(),100000);if(!f.n.active()){done.run();return;}h.runAfterDelay(3,()->finishAttempt(h,f,remaining-1,done));}
 static void rewards(GameTestHelper h){var f=new Fixture(h,204,1);check(h,!f.n.claim(f.p),"Nodule is locked before the boss dies");check(h,f.n.action(f.p,0),"Boss sector starts after its preceding sector");h.runAfterDelay(3,()->finishAttempt(h,f,150,()->{try{check(h,f.n.killed()==25&&(f.n.mask()&2)!=0,"Twenty-four native guards and the actual boss are all required");check(h,f.n.claim(f.p)&&f.p.getInventory().countItem(DeepIndustry.item("raw_asterium"))==3&&f.p.getInventory().countItem(DeepIndustry.item("sundered_drive"))==1&&!f.n.claim(f.p),"Defeated boss unlocks one personal mineral extraction without duplicate loot");h.succeed();}finally{f.close();}}));}
 static void depthsRestore(GameTestHelper h){try(var f=new Fixture(h,206,0)){f.n.action(f.p,0);f.n.tick();var tag=f.n.saveWithFullMetadata(f.w.registryAccess());var n=(DepthsNodeEntity)BlockEntity.loadStatic(f.n.getBlockPos(),f.n.getBlockState(),tag,f.w.registryAccess());n.setLevel(f.w);check(h,n.active()&&n.spawned()==4&&n.killed()==0,"Native encounter save retains active state and genuine actor count");}h.succeed();}
 static void migration(GameTestHelper h){var w=FieldworkTests.vestige(h);var r=CityRegions.region(208,208);var p=DepthsLayout.centre(r,0);int x0=p.getX()&~15,z0=p.getZ()&~15;w.getChunkAt(p);for(int x=x0;x<x0+16;x++)for(int z=z0;z<z0+16;z++)for(int y=14;y<=99;y++)w.setBlock(new BlockPos(x,y,z),Blocks.STONE.defaultBlockState(),2);check(h,DepthsMigration.safe(w,x0,z0),"Natural terrain permits a loaded-chunk retrofit");w.setBlock(p.above(),Blocks.CHEST.defaultBlockState(),3);((ChestBlockEntity)w.getBlockEntity(p.above())).setItem(0,new ItemStack(Items.DIAMOND,9));check(h,!DepthsMigration.safe(w,x0,z0)&&((ChestBlockEntity)w.getBlockEntity(p.above())).countItem(Items.DIAMOND)==9,"A pre-existing player container rejects migration without touching its items");w.setBlock(p.above(),Blocks.GOLD_BLOCK.defaultBlockState(),3);check(h,!DepthsMigration.safe(w,x0,z0),"Foreign building material also rejects migration");h.succeed();}
 static void patterns(GameTestHelper h){var w=h.getLevel();var p=GameplayTests.player(h);var origin=Vec3.atBottomCenterOf(h.absolutePos(new BlockPos(8,4,8)));p.setPos(origin.add(0,0,18));p.setNoGravity(true);var all=new ArrayList<SanctuaryConstruct>();try{int[] expected={5,8,6,7};int i=0;for(var k:List.of(SanctuaryConstruct.Kind.DEPTHS_BASTION,SanctuaryConstruct.Kind.DEPTHS_LENS,SanctuaryConstruct.Kind.DEPTHS_REAPER,SanctuaryConstruct.Kind.DEPTHS_SOVEREIGN)){var b=SanctuaryEntities.TYPES.get(k).get().create(w,EntitySpawnReason.EVENT);b.setPos(origin);all.add(b);check(h,b.beginAttack(p)&&b.pattern()==expected[i++],"Each new boss has its own real telegraphed opening attack");check(h,b.maxIntegrity()>=3600&&k.height>=9,"Each boss is physically monumental with finite layered health");}check(h,!SanctuaryConstruct.Kind.DEPTHS_SENTINEL.boss()&&SanctuaryConstruct.Kind.DEPTHS_RIFLE.ranged(),"New enemy roles are distinct from bosses");}finally{all.forEach(Entity::discard);GameplayTests.cleanup(p);}h.succeed();}
}
